<?php require 'config.php';$pageTitle='Liên hệ';$success='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$subject=trim($_POST['subject']??'');$message=trim($_POST['message']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$message==='')$error='Vui lòng nhập họ tên, email hợp lệ và nội dung.';else{$st=$pdo->prepare('INSERT INTO contacts(full_name,email,subject,message,created_at) VALUES(?,?,?,?,NOW())');$st->execute([$name,$email,$subject,$message]);$success='Gửi liên hệ thành công. Cảm ơn bạn!';}}require 'includes/header.php';?><h1 class="section-title">Liên hệ với GameGear</h1><div class="row g-4"><div class="col-md-5"><div class="content-card h-100"><h4>Chúng tôi luôn sẵn sàng hỗ trợ</h4><p>Gửi câu hỏi về sản phẩm, đơn hàng hoặc góp ý cho cửa hàng.</p><p>📍 Địa chỉ: Hà Nội, Việt Nam</p><p>☎ Điện thoại: 0123 456 789</p><p>✉ Email: support@gamegear.local</p><p class="small-muted">Thông tin liên hệ trên là dữ liệu minh họa cho đồ án.</p></div></div><div class="col-md-7"><form method="post" class="content-card"><?php if($success): ?><div class="alert alert-success"><?= e($success) ?></div><?php endif; ?><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><div class="mb-3"><label class="form-label">Họ tên</label><input class="form-control" name="full_name" required></div><div class="mb-3"><label class="form-label">Email</label><input class="form-control" type="email" name="email" required></div><div class="mb-3"><label class="form-label">Tiêu đề</label><input class="form-control" name="subject"></div><div class="mb-3"><label class="form-label">Nội dung</label><textarea class="form-control" name="message" rows="5" required></textarea></div><button class="btn btn-red">Gửi liên hệ</button></form></div></div><?php require 'includes/footer.php';?>
